import React, { useState, useEffect, useRef } from 'react';
import { useParams } from 'react-router-dom';
import axios from 'axios';
import SockJS from 'sockjs-client';
import { Client } from '@stomp/stompjs';

const ChatRoom = () => {
    const { roomId, roomName } = useParams();
    const [messages, setMessages] = useState([]);
    const [messageContent, setMessageContent] = useState('');
    const [userId, setUserId] = useState(localStorage.getItem('userId'));
    const stompClient = useRef(null);

    useEffect(() => {
        connectToChatRoom();
        fetchMessages();

        return () => {
            if (stompClient.current) {
                stompClient.current.deactivate();
            }
        };
    }, []);

    const fetchMessages = async () => {
        try {
            const response = await axios.get(`http://172.30.1.52:8081/api/chatrooms/${roomId}/messages`);
            const messagesData = Array.isArray(response.data) ? response.data : [];
            setMessages(messagesData);
        } catch (error) {
            console.error('Failed to fetch messages:', error);
        }
    };

    const connectToChatRoom = () => {
        const socket = new SockJS('http://172.30.1.52:8081/ws');
        stompClient.current = new Client({
            webSocketFactory: () => socket,
            onConnect: () => {
                console.log('Connected to chat room');
                stompClient.current.subscribe(`/topic/public`, (message) => {
                    const receivedMessage = JSON.parse(message.body);
                    if (receivedMessage.roomId === roomId) {
                        setMessages((prevMessages) => [...prevMessages, receivedMessage]);
                    }
                });
            },
            onStompError: (frame) => {
                console.error('Broker reported error: ' + frame.headers['message']);
                console.error('Additional details: ' + frame.body);
            },
        });

        stompClient.current.activate();
    };

    const sendMessage = async () => {
        if (messageContent.trim() && stompClient.current && userId) {
            const message = {
                sender: userId,
                content: messageContent,
                roomId: roomId,
            };
            stompClient.current.publish({
                destination: '/app/chat.sendMessage',
                body: JSON.stringify(message),
            });

            try {
                await axios.post(`http://172.30.1.52:8081/api/chatrooms/${roomId}/messages`, message);
                setMessages((prevMessages) => [...prevMessages, message]);
                setMessageContent('');
            } catch (error) {
                console.error('Failed to send message:', error);
            }
        }
    };

    const renderItem = (item, index) => (
        <div key={index} style={{ display: 'flex', flexDirection: 'column', marginBottom: '10px' }}>
            <strong>{item.sender}:</strong>
            <span>{item.content}</span>
        </div>
    );

    return (
        <div style={{ padding: '20px' }}>
            <h2>{roomName}</h2>
            <div style={{ maxHeight: '400px', overflowY: 'scroll', marginBottom: '20px' }}>
                {messages.map((item, index) => renderItem(item, index))}
            </div>
            <div style={{ display: 'flex' }}>
                <input
                    type="text"
                    value={messageContent}
                    onChange={(e) => setMessageContent(e.target.value)}
                    placeholder="Type a message..."
                    style={{ flex: 1, marginRight: '10px', padding: '10px' }}
                />
                <button onClick={sendMessage} style={{ padding: '10px' }}>
                    Send
                </button>
            </div>
        </div>
    );
};

export default ChatRoom;
